\i security/candidates/local_security_tests.sql
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='hasad_api' AND has_function_privilege('authenticated',p.oid,'EXECUTE')), 'authenticated has exactly the two intended RPC EXECUTE grants');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='hasad_api'), 'only whoami and products_list API functions exist');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_roles r ON r.oid=p.proowner WHERE n.nspname='hasad_api' AND r.rolname='hasad_rpc_owner' AND p.prosecdef), 'both RPCs are SECURITY DEFINER owned by restricted owner');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='hasad_api' AND NOT has_function_privilege('anon',p.oid,'EXECUTE')), 'anon denied EXECUTE on both RPCs');
SELECT pg_temp.assert_true(NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='hasad_api' AND a.grantee=0 AND a.privilege_type='EXECUTE'), 'PUBLIC denied EXECUTE on both RPCs');
SELECT pg_temp.assert_true((SELECT NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolinherit FROM pg_roles WHERE rolname='hasad_rpc_owner'), 'execution owner is NOLOGIN NOBYPASSRLS NOINHERIT and unprivileged');
SELECT pg_temp.assert_true(NOT pg_has_role('authenticated','hasad_rpc_owner','MEMBER'), 'authenticated cannot assume or inherit RPC owner');
SELECT pg_temp.assert_true(NOT has_schema_privilege('authenticated','hasad','USAGE'), 'authenticated cannot address private hasad schema');
SELECT pg_temp.assert_true(NOT has_function_privilege('authenticated','hasad.has_permission(uuid,uuid,boolean,text)','EXECUTE'), 'authenticated cannot invoke internal permission resolver');
SELECT pg_temp.assert_true(NOT has_schema_privilege('anon','hasad_api','USAGE'), 'anon has no API schema USAGE');
SELECT pg_temp.assert_true(NOT has_schema_privilege('hasad_rpc_owner','hasad','CREATE') AND NOT has_schema_privilege('hasad_rpc_owner','hasad_api','CREATE'), 'temporary schema CREATE grants are revoked');
SELECT pg_temp.assert_true(NOT has_function_privilege('service_role','hasad_api.whoami()','EXECUTE') AND NOT has_function_privilege('service_role','hasad_api.products_list()','EXECUTE'), 'BYPASSRLS service_role receives no RPC EXECUTE');
SELECT pg_temp.assert_true(NOT has_table_privilege('service_role','hasad.products','SELECT'), 'BYPASSRLS service_role receives no direct product table grant');
SELECT pg_temp.assert_true((SELECT count(*)=8 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='hasad' AND c.relkind='r' AND has_table_privilege('hasad_rpc_owner',c.oid,'SELECT') AND NOT has_table_privilege('hasad_rpc_owner',c.oid,'INSERT') AND NOT has_table_privilege('hasad_rpc_owner',c.oid,'UPDATE') AND NOT has_table_privilege('hasad_rpc_owner',c.oid,'DELETE')), 'execution owner has SELECT-only grants on exactly eight API input tables');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='hasad_api' AND p.proconfig @> ARRAY['search_path=pg_catalog, pg_temp']), 'both SECURITY DEFINER RPCs have pinned search_path');
SELECT pg_temp.assert_true((SELECT count(*)=2 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='hasad_api' AND t.typname IN ('company_context_dto','product_dto') AND has_type_privilege('authenticated',t.oid,'USAGE') AND NOT has_type_privilege('anon',t.oid,'USAGE')), 'return DTO types usable by authenticated and denied to anon');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM hasad.permissions WHERE code='products.read' AND module='products'), 'one products.read catalogue definition');
SELECT pg_temp.assert_true(NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='hasad_api' AND p.proname NOT IN ('whoami','products_list')), 'no unintended API RPCs');
